import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"屯","description":"焦氏易林注 - 屯","frontmatter":{"title":"屯","description":"焦氏易林注 - 屯"},"headers":[],"relativePath":"classics/jiaoyilin/003.md","filePath":"classics/jiaoyilin/003.md"}'),l={name:"classics/jiaoyilin/003.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="屯" tabindex="-1">屯 <a class="header-anchor" href="#屯" aria-label="Permalink to “屯”">​</a></h1><h3 id="屯-1" tabindex="-1">屯 <a class="header-anchor" href="#屯-1" aria-label="Permalink to “屯”">​</a></h3><h3 id="屯之乾" tabindex="-1">屯之乾 <a class="header-anchor" href="#屯之乾" aria-label="Permalink to “屯之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>泛泛柏舟，流行不休。耿耿寤寐，心懷大憂。仁不逢時，退隱窮居。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>九家及荀爽皆以乾為河，《易林》亦以乾為江河，乃知荀及九家之所本為河，故曰泛泛、曰流行。乾由屯變來，屯之乾亦乾之屯，屯下震為木、為舟，故曰柏舟。坎為心、為憂、為隱，艮為時、為居，故曰退隱窮居。《左傳》雲：「震之離亦離之震」，林所本也。《詩邶風》：「泛彼柏舟，亦泛其流」，《毛傳》謂「婦以柏舟自比，茲曰退隱」，義與毛異。○退，各本皆作復，依鹹之大過校。</p><h3 id="屯之坤" tabindex="-1">屯之坤 <a class="header-anchor" href="#屯之坤" aria-label="Permalink to “屯之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>採薪得麟，大命隕顛。豪雄爭名，天下四分。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坤為薪、為文，故為麟，坤死故曰大命隕顛。遇卦屯震為豪雄，艮為名，初至五正反艮震，故曰爭名。坤為天下，坤拆故四分。《公羊哀公十四年》：「薪採者獲麟，孔子聞之，反袂拭面涕沽巾，自知死不久也。」</p><h3 id="屯之屯" tabindex="-1">屯之屯 <a class="header-anchor" href="#屯之屯" aria-label="Permalink to “屯之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>兵徵大宛，北出玉關。與胡寇戰，平城道西，七日絕糧，身幾不全。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎眾、坤眾，故曰兵。震為徵，坎位西，故曰大宛。艮為關，震為玉、為出，坤位北，故曰北出玉關。坤陰為胡，坎為寇，正覆艮震，故曰戰。艮為城、為道，坎為平、為西，震數七，伏乾為日，震為糧，坤虛，故曰七日絕糧。坤為身、為死，故曰不全。《史記》：「高帝至平城，為匈奴所圍，七日不得食」。大宛，西域國名，《史記》有《大宛傳》。坎坤全用先天卦位。</p><h3 id="屯之蒙" tabindex="-1">屯之蒙 <a class="header-anchor" href="#屯之蒙" aria-label="Permalink to “屯之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>山崩谷絕，大福既竭。涇渭失紀，玉歷既已。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>二四艮覆，故曰山崩、曰谷絕，乾為福、為大，三至五乾伏坤喪，故大福竭。坤水、坎水混合漫流，故曰涇渭失紀。震為玉、為時，故為歷。《論語》：「天之暦數在爾躬，天祿永終」。玉歷既己者，言暦數盡也，《史記周本紀》：」幽王二年，三川竭，岐山崩」，《竹書幽王二年》：「涇渭洛竭，岐山崩」，後幽王被犬戎所殺，西周亡。○既，從宋元本，汲古作盡。</p><h3 id="屯之需" tabindex="-1">屯之需 <a class="header-anchor" href="#屯之需" aria-label="Permalink to “屯之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>夏臺羑里，湯文所厄。鬼侯輸賄，商王解合。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>通《晉》。艮為臺、為裡，上離故曰夏臺。《書康誥》：「羑」，王肅雲：「道也。」艮為道，故曰羑里。坎為水，下有艮火，故曰湯，離為文，桀囚湯夏臺，紂囚文王於羑里，故曰湯文所厄。坎為鬼，四為諸侯，故曰鬼侯。艮為貝，艮手為輸，故曰輸賄。乾為王、為言，故曰商王。坎為合，史稱「鬼侯進女於紂，女不喜淫，醢。」鬼侯與此異。○湯文，從宋元本，汲古作文王，非。輸，依汲古，宋元本皆作俞。</p><h3 id="屯之訟" tabindex="-1">屯之訟 <a class="header-anchor" href="#屯之訟" aria-label="Permalink to “屯之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>泥滓汙辱，棄捐溝瀆。所共笑哭，終不顯錄。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>坎為泥滓、為汙辱、為溝瀆、為眾，伏震為笑哭。坎為隱伏，故不顯錄。○滓，從元本，宋本、汲古作津。所共，從宋本，汲古、元本作為眾。</p><h3 id="屯之師" tabindex="-1">屯之師 <a class="header-anchor" href="#屯之師" aria-label="Permalink to “屯之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>李梅冬實，國多盜賊。擾亂並作，君不得息。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>互震為李梅，乾為木果，坎為冬，故曰冬實。《左氏春秋僖公三十三年十二月》：「李梅實，書不時也」，坤為國，坎為盜賊，坤眾，故曰多。坤為亂，震為擾、為作、為君，震行故不息。○得，宋元本作能，依汲古。</p><h3 id="屯之比" tabindex="-1">屯之比 <a class="header-anchor" href="#屯之比" aria-label="Permalink to “屯之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>獐鹿逐牧，飽歸其居。反還次舍，無有疾故。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為獐鹿，坤為牧，反震為逐，坎中滿，故曰飽，艮為居、為次舍，反震為反還，坎為疾，坤為死、為故，艮堅，故無有疾故。</p><h3 id="屯之小畜" tabindex="-1">屯之小畜 <a class="header-anchor" href="#屯之小畜" aria-label="Permalink to “屯之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>夾河為婚，期至無船。搖心失望，不見所歡。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。坎為河，四上下皆陰，故曰夾河。艮為時、為期，坎為婚，震為船，坎伏故無船。坎為心，震為搖，艮為望，坤失，故曰搖心失望。震為歡，坎伏，故不見所歡。○搖，從元本，宋本、汲古皆作淫，非。《戰國策》：「楚王曰：寡人心搖搖如懸旌。」</p><h3 id="屯之履" tabindex="-1">屯之履 <a class="header-anchor" href="#屯之履" aria-label="Permalink to “屯之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>百足俱行，相輔為強。三聖翼事，王室寵光。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。互震為足、為百、為行，故曰百足俱行。百足，蟲名，《淮南子》：「百足之蟲，至死不僵」是也。兌為輔，坎為聖，震數三，故曰三聖。震為翼，坎為事，故曰翼事。震為王，坎為宮室，艮為光，故曰王室寵光。三聖謂文、武、周公。</p><h3 id="屯之泰" tabindex="-1">屯之泰 <a class="header-anchor" href="#屯之泰" aria-label="Permalink to “屯之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>坐位失處，不能自居。調攝違和，陰陽顛倒。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>言與天尊地卑之義相反也，故曰陰陽顛倒。○調攝違和，宋元本作賊破王邑，因與上下文義不協，故從汲古。</p><h3 id="屯之否" tabindex="-1">屯之否 <a class="header-anchor" href="#屯之否" aria-label="Permalink to “屯之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>登幾上輿，駕駟南遊。合縱散橫，燕齊以強。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為幾，坤為輿，乾為馬、為行，故曰駕駟。乾位南，故曰南遊。坤為順，故曰合縱。艮東北為燕，巽為齊，乾健艮堅，故曰強。○齊，汲古作秦，非，依宋元本。</p><h3 id="屯之同人" tabindex="-1">屯之同人 <a class="header-anchor" href="#屯之同人" aria-label="Permalink to “屯之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>三系維弩，無益於輔。城弱不守，郭君受討。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>互巽為繩，故曰系，《離》卦數三，故曰三系。《後漢書劉昭輿服志》：「凡先合單紡為一系」是也。伏坎為弓、為弩。維，系也。言以三系之絲繫於弩上太弱，故曰無益於輔。伏坤為城，坤柔故曰城弱。坤為郭，伏震為君、為討伐，故曰郭君受討。郭，國名，滅於齊。○系維，從汲古，宋本、元本作孫荷。城，從宋本，汲古作域。郭，宋元本作邦，汲古作郭。按：元本舊註雲「三孫謂季孫、叔孫、孟孫」，昭二十五年三家反攻公，公遜齊，疑林詞指此，非。</p><h3 id="屯之大有" tabindex="-1">屯之大有 <a class="header-anchor" href="#屯之大有" aria-label="Permalink to “屯之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>河伯大呼，津不得渡。船空無人，往來亦難。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>丁雲：「河伯，水神，《援神契》：「河者，水之伯」。按：此用遇卦屯象，坎為河，震為伯、為呼，故曰河伯大呼。艮為止，故津不得渡。震為船，坤虛，故曰船空。震為人，坎伏，故無人。震為往，震覆，故往來難。</p><h3 id="屯之謙" tabindex="-1">屯之謙 <a class="header-anchor" href="#屯之謙" aria-label="Permalink to “屯之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>甘露醴泉，太平機關。仁德感應，歲樂民安。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>互坎為水，坤為水，故曰甘露、曰醴泉。坎為平、為機，艮為關，震為仁德、為歲、為樂，坎為心，故曰感應。坤為民，艮為安。舊註《瑞應圖》雲「王者，德至則甘露降於松柏。」《六帖》雲：「醴泉太平則出。」</p><h3 id="屯之豫" tabindex="-1">屯之豫 <a class="header-anchor" href="#屯之豫" aria-label="Permalink to “屯之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>重茵厚席，循皋採藿。雖躓不懼，復反其宅。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為茵席，正覆震，故曰重茵厚席。艮為皋，震為藿，艮手，故曰採藿。坎為憂懼、為躓，震樂，故不懼。艮為宅，震為反，故曰反宅。○復反，宋元本作反覆。宅，元本作處，均依汲古。皋，汲古作高，依宋元本。</p><h3 id="屯之隨" tabindex="-1">屯之隨 <a class="header-anchor" href="#屯之隨" aria-label="Permalink to “屯之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>太乙駕騮，從天上來。徵我叔季，封為魯侯，無有兇憂。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>太乙，星名，即北辰也。艮為星，震為馬，艮在震上，故曰駕騮。否上之初，故曰從天上來。艮為叔季、為求，故曰徵我叔季。兌為魯，震為侯，故曰魯侯。坎為憂，震樂，故無有兇憂。○宋元本無第五句，依汲古。</p><h3 id="屯之蠱" tabindex="-1">屯之蠱 <a class="header-anchor" href="#屯之蠱" aria-label="Permalink to “屯之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>南巴六安，石斛戟天。所指不已，已老復一。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>將耋乃嫁，墟敝室舊，更為新家。丁雲：「石斛、巴戟天，皆藥草名，《神農本草經》曰：石斛出六安，巴戟天出巴郡。」按：震為南，艮為城邑，故曰南巴。互大坎數六，艮為安，故曰六安。艮為石，震為斛，故曰石斛，艮為刀、為戟，在上，故曰戟天。艮為指，震為反、為復，已老復一者，言己年老，復其一子，免其賦役也。艮為堅，故為耋。震為嫁，故曰將耋乃嫁。艮為墟、為室，巽為敝，故曰墟敝室舊。艮為光明、為新、為家。○巴六，從宋元本，汲古作己大，非。斛，依汲古本，宋元本訛解。己老復一，宋元木作耋老復丁，無將耋乃嫁句，此從汲古，以已與一韻，嫁與家韻。墟敝室舊，宋元本作敝室舊墟，以墟與家韻，以文勢言不如汲古，故從之。</p><h3 id="屯之臨" tabindex="-1">屯之臨 <a class="header-anchor" href="#屯之臨" aria-label="Permalink to “屯之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>家給人足，頌聲並作。四夷賓伏，乾戈韜閣。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>通《遯》。艮為家，震為人、為足，震為音聲、為言、為作，故曰頌聲並作。震卦數四，坤為夷，故曰四夷。震為賓客，伏者，言四夷賓於王庭。巽為伏，兌為斧、為乾戈，坤藏故曰乾戈韜閣。○伏，從宋元本，汲古作服。伏、服古通用。</p><h3 id="屯之觀" tabindex="-1">屯之觀 <a class="header-anchor" href="#屯之觀" aria-label="Permalink to “屯之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>東鄰嫁女，為王妃後。莊公築館，以尊王母。歸於京師，季薑悅喜。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>通《大壯》。震為東鄰、為嫁，兌為女、為妃，震為王、為木，故為桓。莊，訛字也。震又為公，故曰桓公。艮為館、為築，坤為母，伏乾為王，故曰王母。震為歸，坤為京師，艮為季，巽為薑，伏震為喜。按：《左傳莊元年》：「魯為主築館以逆王姬，非為王后」，又桓九年春紀季薑歸於京師，為桓王后。林詞全用此事，據《穀梁疏》：「魯為主方書歸為主，則必築館」，然則莊為桓之訛字無疑。</p><h3 id="屯之噬嗑" tabindex="-1">屯之噬嗑 <a class="header-anchor" href="#屯之噬嗑" aria-label="Permalink to “屯之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>陳媯敬仲，兆興齊薑。營邱是適，八世大昌。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為陳，坎為仲，艮為篤敬，故曰敬仲。坎為兆，伏巽為齊、為薑，互艮為營邱，震往，故曰適。艮為世，數八，震為昌。媯，陳姓，敬仲，即公子完。莊二十二年奔齊，初懿氏卜妻，敬仲曰：「有媯之後，將育於薑」，故曰兆興齊薑。</p><h3 id="屯之賁" tabindex="-1">屯之賁 <a class="header-anchor" href="#屯之賁" aria-label="Permalink to “屯之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>路多枳棘，步刺我足。不利旅客，為心作毒。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮震為道路，坎為枳棘、為刺，震為步、為足、為旅客，坎險故不利，坎為心、為毒。</p><h3 id="屯之剝" tabindex="-1">屯之剝 <a class="header-anchor" href="#屯之剝" aria-label="Permalink to “屯之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>天官列宿，五神共舍。宮闕光堅，君安其居。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為官、為星，故曰天官列宿。漢樂章有五神歌曰：五神相，包四鄰。如淳曰，五神相，太一也，蓋即五星也。艮為舍，反震為神，坤，五行數五，故曰五神共舍。艮為宮闕、為光、為堅、為居、為安，一陽止於上，故曰君安其居，故曰共舍，言五陰承一陽也。</p><h3 id="屯之復" tabindex="-1">屯之復 <a class="header-anchor" href="#屯之復" aria-label="Permalink to “屯之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>牧羊稻園，聞虎呻喧。懼畏惕息，終無禍患。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤為養、為牧，震為羊，震為稻，坤為園、為虎，震為喧，伏乾，乾惕故懼畏惕息。坤為禍，震樂，故無。○無，從宋元，汲古作免。</p><h3 id="屯之無妄" tabindex="-1">屯之無妄 <a class="header-anchor" href="#屯之無妄" aria-label="Permalink to “屯之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>鳴條之災，北奔犬胡。左祍為長，國號匈奴。主君旄頭，立尊單於。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為鳴、為木，故曰鳴條。乾伏坤位北，坤又為胡，艮犬，故曰北奔犬胡。震為祍、為左、為長，《論語》：「吾其被髮左祍」，胡俗也。艮為國、為奴僕，震為號，故曰國號匈奴。震為主，乾為君、為頭，震為多發，故曰主君旄頭。震為立，艮為尊，乾君故曰單於，《史記》：「湯伐桀於鳴條」，又《匈奴傳》索隱引樂彥《括地譜》雲：「湯放桀鳴條，其子獯粥妻桀之眾妾，避居北野，隨畜移徙」，中國謂之匈奴。旄頭，被髮也。《漢官儀》：「舊選羽林為旄頭，被髮先驅」是其證。由林詞觀之，《括地譜》之說與古故實合。○災，宋元本作圖，依汲古。</p><h3 id="屯之大畜" tabindex="-1">屯之大畜 <a class="header-anchor" href="#屯之大畜" aria-label="Permalink to “屯之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>克已潔身，逢禹巡狩。錫我玄圭，拜受福佑。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為身，退在上，故曰潔身。乾為王，震出，故曰逢禹巡狩。震為玄黃、為玉，乾為錫，故曰錫我玄圭。艮為拜，乾為福佑。○福，汲古作錫，非，依宋元本。《禹貢》雲：「禹錫玄圭，告厥成功」，圭，宋元、汲古皆作圭，依局本。</p><h3 id="屯之頤" tabindex="-1">屯之頤 <a class="header-anchor" href="#屯之頤" aria-label="Permalink to “屯之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>冬華不實，國多盜賊。疾病難醫，鬼哭其室。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為果實，坤為冬，震為花，坤虛，故花而不實。坤為國，伏巽為盜，正反巽，故多盜。坤為疾病，坤死，故難醫，坤為鬼，震為哭，艮為室，故曰鬼哭其室。</p><h3 id="屯之大過" tabindex="-1">屯之大過 <a class="header-anchor" href="#屯之大過" aria-label="Permalink to “屯之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>襄送季女，至於盪道。齊子旦夕，流連久處。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>兌少故曰季女，伏震為諸侯，故曰襄。震為大塗，故曰盪道。《齊風》：「魯道有盪，齊子發夕」，刺齊襄與文薑亂也。巽為齊，伏震為子，震為旦，兌昧為夕，艮止故流連久處。《左傳桓三年》：「齊侯送薑氏於歡」，註：歡，魯地。繇詞言齊襄與妹亂，既送至魯境，而不忍別也。詞皆本象與對象雜用。陳樸園雲：「齊風，齊子發夕」，釋文引《韓詩》雲：「發，旦也。」今焦氏言齊子旦夕，是《齊詩》以發夕為旦夕，與《韓詩》訓同。</p><h3 id="屯之坎" tabindex="-1">屯之坎 <a class="header-anchor" href="#屯之坎" aria-label="Permalink to “屯之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>朽根倒樹，花葉落去。卒逢火焱，隨風偃僕。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>通《離》。中爻巽為木，故曰根、曰樹，巽敝，故曰朽，曰倒，巽隕落，故花葉落去。《大過》兌為華，離上互也，離上下皆火，互巽風隕，故偃僕。</p><h3 id="屯之離" tabindex="-1">屯之離 <a class="header-anchor" href="#屯之離" aria-label="Permalink to “屯之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>陰變為陽，女化作男。治道得通，君臣相承。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。乾二五之坤成坎，坎為中男、為陽卦，故陰化陽、女作男。坎中爻艮為道路、為臣，震為君，故曰君臣相承。《五行志》：「魏襄王十三年，有女子化為丈夫。」</p><h3 id="屯之鹹" tabindex="-1">屯之鹹 <a class="header-anchor" href="#屯之鹹" aria-label="Permalink to “屯之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>炎絕續光，火滅復明。簡易理得，以成乾功。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>下艮為火，故曰炎，上兌為絕，故曰炎絕。巽繩為續，艮為火、為光，巽伏，故光滅，乾日，故復明。乾簡坤易，中爻乾，故曰以成乾功。○火，依宋元本，汲古作光，非。以，汲古作仍，依宋元本。</p><h3 id="屯之恆" tabindex="-1">屯之恆 <a class="header-anchor" href="#屯之恆" aria-label="Permalink to “屯之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>多載重負，捐棄於野。予母誰子，但自勞苦。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>坤震皆為車，坤厚載物，故曰多載。艮為負，坤重，故曰重負。坤為野，兌附決，故曰捐棄。坤母震子，兌決，故無子。坤致役萬物，故曰勞苦。多用伏象。○予母誰子，依宋元本，諸本作「王母離子」，非。</p><h3 id="屯之遯" tabindex="-1">屯之遯 <a class="header-anchor" href="#屯之遯" aria-label="Permalink to “屯之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>江河海澤，眾利室宅。可以富有，飲御嘉客。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為江河海澤，巽為利，艮為室宅，乾為富，伏兌為口，故曰飲。震為嘉客。○室，汲古及宋本皆作安，惟元本作室。</p><h3 id="屯之大壯" tabindex="-1">屯之大壯 <a class="header-anchor" href="#屯之大壯" aria-label="Permalink to “屯之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>冬採薇蘭，地凍堅坼。利走東北，暮無所得。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦屯象。坎為冬，艮手為採，震為薇蘭，坤為地，履霜堅冰，故曰地凍堅坼。震為東北、為走，伏巽為利，坤為暮，坤虛故無得。○坼，各本多誤難，致韻不協，惟宋本作坼，元本作折。東，宋元本作室，從汲古。</p><h3 id="屯之晉" tabindex="-1">屯之晉 <a class="header-anchor" href="#屯之晉" aria-label="Permalink to “屯之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>鳥鳴嘻嘻，天火將起。燔我室屋，災及妃後。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>《左傳襄十三年》：「有鳥鳴於宋太廟，曰嘻嘻出出，宋火伯姬被焚，卒」，晉離為鳥，離正反皆兌口，故曰嘻嘻。離為火，艮為天，亦為火，故曰天火。艮為室屋，坤為妃後，火多故曰燔、曰災。○鳥鳴，依宋元本，汲古作鳥鵲，嘻，同嘻，與左氏同。</p><h3 id="屯之明夷" tabindex="-1">屯之明夷 <a class="header-anchor" href="#屯之明夷" aria-label="Permalink to “屯之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>蠆室蜂戶，螫我手足。不可進取，為身害速。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦屯象。坎為室、為毒，坤為戶，伏巽為蟲，故曰蠆室蜂戶。坎為棘、為刺、為螫，艮為手，震為足、為進取，坤兇，故不可進取，坤為身、為害，震為速。○速，從宋元本，汲古等本多作咎，與足不韻。</p><h3 id="屯之家人" tabindex="-1">屯之家人 <a class="header-anchor" href="#屯之家人" aria-label="Permalink to “屯之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>崔嵬北嶽，天神貴客。溫仁正直，主布恩德。閔哀不已，蒙受大福。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《屯》象。坎北艮山，故曰北嶽。震為神、為仁、為客，坎為憂，故曰閔哀。震為恩德、為大福。○閔哀，宋元本、汲古本皆作開衣，非，依局本。閔哀不已者，言悲憫人世，予人以福也。</p><h3 id="屯之睽" tabindex="-1">屯之睽 <a class="header-anchor" href="#屯之睽" aria-label="Permalink to “屯之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>伯蹇叔盲，莫與守牧。失我衣裘，代己除服。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此用《屯》象。震為伯，坎蹇，故曰伯蹇。艮為叔，互大離，故曰叔盲。坤為牧，坤寡，故莫與守牧。震為衣裘、為服，坤喪坎盜，故曰失。除，治也，言衣裘為人盜去，代我治理服用也。○第二句宋元本作莫為守床，第四句作伐民除鄉，均依汲古。</p><h3 id="屯之蹇" tabindex="-1">屯之蹇 <a class="header-anchor" href="#屯之蹇" aria-label="Permalink to “屯之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>為季求婦，家在東海。水長無船，不見所歡。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為季、為求，伏兌為艮婦，艮為家，互離為東，坎為海、為水，震為船，震覆，故無船。震為歡，震覆坎伏，故不見。○所，汲古本誤欣，依宋元本。</p><h3 id="屯之解" tabindex="-1">屯之解 <a class="header-anchor" href="#屯之解" aria-label="Permalink to “屯之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>山陵邱墓，魂魄失舍。精誠盡竭，長寢不覺。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>此用《屯》象。艮為山陵、為邱墓，坎為舍、為心、為精誠，坎失，故竭盡。坎為夜、為寢，坤死，故不覺。○誠，汲古作神，從元本。</p><h3 id="屯之損" tabindex="-1">屯之損 <a class="header-anchor" href="#屯之損" aria-label="Permalink to “屯之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>踦牛失角，下山傷軸，失其利祿。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤為牛，艮為角，兌毀折，故牛踦、故角失。踦，蹇也。艮為山，坤為下，坎為軸，兌折，故傷軸。伏巽為利，坤為失。○踦，宋本作騎，依汲古。</p><h3 id="屯之益" tabindex="-1">屯之益 <a class="header-anchor" href="#屯之益" aria-label="Permalink to “屯之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>水載船舟，無根以浮。往來溶溶，心勞且憂。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>坤為水，震為船，坤為載，巽下斷，在水上故曰無根以浮。震為往，又為反，故曰往來，坤水，故曰溶溶。伏大坎為心、為勞、為憂。○載，宋、汲古誤戴，從元本。</p><h3 id="屯之夬" tabindex="-1">屯之夬 <a class="header-anchor" href="#屯之夬" aria-label="Permalink to “屯之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>有鳥來飛，集於宮樹。鳴聲可惡，主將出去。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>屯艮為鳥、為飛、為宮、為集、為木，故曰集於宮樹。下震為鳴、為聲，坤為惡，下震為主、為出，此用《左傳》，見前《晉》卦。○宮，宋、汲古作古，非，依元刊。</p><h3 id="屯之姤" tabindex="-1">屯之姤 <a class="header-anchor" href="#屯之姤" aria-label="Permalink to “屯之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>東徙不時，觸患離憂。井泥無濡，思叔舊居。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為東、為徙，艮為時，艮覆，故不時。坤為憂患，震為觸，坤為井、為泥，艮為叔、為居，坤為舊，剝窮上反下，言複舊為剝艮也。</p><h3 id="屯之萃" tabindex="-1">屯之萃 <a class="header-anchor" href="#屯之萃" aria-label="Permalink to “屯之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>黃帝所生，伏羲之宇。兵刃不至，利以居止。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>通《大畜》。震為黃、為帝、為生，故曰黃帝所生。巽為伏，艮為宇，故曰伏羲之宇。艮剛在上為兵刃，艮止，故不至。巽為利，艮為居止。按：伏羲，都陳，黃帝為有熊國君，少典之子。皇甫謐曰：「有熊，今河南新鄭，非陳地」，焦氏時古籍尚多，或別有所據歟。○伏，元本作宓。孟康《漢書》註：「宓，今伏字」，皇甫謐雲：「伏羲或謂之宓羲。考諸經史緯候，無宓羲之號，必後世傳寫誤虙為宓，孔子弟子宓不齊、濟南伏生即子賤之後，是知虙與伏古字通用，後誤為宓。」按皇甫說是，故不從元本，依宋本、汲古。</p><h3 id="屯之升" tabindex="-1">屯之升 <a class="header-anchor" href="#屯之升" aria-label="Permalink to “屯之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>東山拯亂，處婦思夫。勞我君子，役無休已。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>艮為陵、為東，故曰東山。坤為亂，伏艮為手、為拯。巽為婦，在內，故曰處婦。坤為思，震為夫，坤為勞，震為君子，坤為役，艮止，故已，艮覆故不已。詞皆用《東山》詩意。○無、已，汲古本作役使休止，從宋元本。</p><h3 id="屯之困" tabindex="-1">屯之困 <a class="header-anchor" href="#屯之困" aria-label="Permalink to “屯之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>跛躓未起，失利後市，不得鹿子。坎蹇，故跛躓。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>坎伏，故未起。互巽為利市，坎失，故失利後市。震為鹿、為子，震伏，故不得。○失，依汲古，宋元本皆作先。</p><h3 id="屯之井" tabindex="-1">屯之井 <a class="header-anchor" href="#屯之井" aria-label="Permalink to “屯之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>大蛇當路，使季畏懼。湯火之災，切近我膚。賴其天幸，趨於王廬。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>巽為蛇，伏震為大塗，故曰大蛇當路。伏艮為季，坎為畏懼，中爻離上坎，故曰湯火。伏艮為膚、為廬，震為王、為走，故曰趨於王廬。○季，從宋元本，汲古等本皆作我，非。緣此用漢高斬當路蛇事。王，汲古本作主，亦非。</p><h3 id="屯之革" tabindex="-1">屯之革 <a class="header-anchor" href="#屯之革" aria-label="Permalink to “屯之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>從容長閑，遊戲南山。拜祠禱神，神使無患。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。反正艮，艮止，故從容。震為遊戲、為南，艮為山，故曰南山。艮手為拜、為祠，震為禱、為神，坎為患，震樂故無患。全用旁通。○禱，汲古作祀，無作免，義皆可通，然禱為震象較切。故從宋元本。</p><h3 id="屯之鼎" tabindex="-1">屯之鼎 <a class="header-anchor" href="#屯之鼎" aria-label="Permalink to “屯之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>區脫康居，慕義入朝。湛露之歡，三爵畢恩。復歸野廬，與母相扶。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤虛故曰區脫。《史記匈奴傳》：「東胡與匈奴中間有棄地千餘裡，各居其邊為區脫」是也。坎西。康居，西方國，坤國，故曰康居。坤為義，坎為心，故曰慕義，震往，故曰入朝。坎為露，震為歡、為爵，數三，故曰三爵。坤為野，艮為廬，震為反、為歸，故曰復歸野廬。坤為母，艮手為扶，初至五正反皆艮，故曰相扶。湛露，《詩》篇名，天子宴諸侯入朝之詩。○義，汲古作仁，乾雖為仁，然林詞皆用旁通，坤義合也，故從宋本。復，從汲古，宋本作後，雖亦震象，然不如復字於文理適。</p><h3 id="屯之震" tabindex="-1">屯之震 <a class="header-anchor" href="#屯之震" aria-label="Permalink to “屯之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>龜鱉列市，河海饒有。長財善賈，商季悅喜。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>互艮為龜鱉，伏巽為市。坎為河海，坎眾，故曰饒有。伏巽為利、為長、為商賈，艮為季，震為列、為善，又為悅喜。○財，宋元本皆作錢，賈作價，均依汲古。</p><h3 id="屯之艮" tabindex="-1">屯之艮 <a class="header-anchor" href="#屯之艮" aria-label="Permalink to “屯之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>年常蒙慶，今歲受福。三夫採芑，出必有得。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為年、為慶、為福、為夫，數三，故曰三夫。艮手為採，震為芑，《詩小雅》：「薄言採芑」，疏：「芑，似苦菜。」震為出，坎為得。○夫，汲古作伏，依宋元本。芑，宋元本作葩，依汲古。</p><h3 id="屯之漸" tabindex="-1">屯之漸 <a class="header-anchor" href="#屯之漸" aria-label="Permalink to “屯之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>二人俱東，道怒爭訟。意乖不同，使君忷忷。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>通《歸妹》。震為人、為東，兌卦數二，故曰二人俱東。震為大塗、為怒，故曰道怒。震為言，兌亦為言，故爭訟。坎為意、為憂，故為忷忷。震為君。忷，同恟，懼也。○怒，宋本、汲古作路，依元本。使君忷忷，汲古作使我兇兇，依宋元本。</p><h3 id="屯之歸妹" tabindex="-1">屯之歸妹 <a class="header-anchor" href="#屯之歸妹" aria-label="Permalink to “屯之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>樹我藿豆，為鹿兔食。君不慎護，秋無收入。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為藿豆、為立，故為樹。震為足、為走，故為鹿兔。兌口為食。震為君，坎為憂恤，兌正秋，兌毀，故秋無收入。○我，依宋元本，汲古作栽。為鹿兔食，宋元本作鹿兔為食，從汲古。慎，宋元本作恤，亦依汲古。</p><h3 id="屯之豐" tabindex="-1">屯之豐 <a class="header-anchor" href="#屯之豐" aria-label="Permalink to “屯之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>黃鳥悲鳴，愁不見星。困於鷙鳥，鸇使我驚。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震為黃、為鳥、為鳴，互大坎，故悲鳴，故愁。離為星，坎伏，故不見。伏艮為鷙鳥、為鸇，坎為困，震為鷙。○下二句依宋元本，汲古作「困於鷙鸇、使我心驚」。又元本困訛因。</p><h3 id="屯之旅" tabindex="-1">屯之旅 <a class="header-anchor" href="#屯之旅" aria-label="Permalink to “屯之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>雙鳧俱飛，欲歸稻池。經涉萑澤，為矢所射，傷我胸臆。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。兌卦數二，震為鳧、為飛，故曰雙鳧俱飛。兌為池，震為稻，故曰稻池，故曰萑澤。震為涉，坎為矢，震為射，兌為傷，艮為胸臆。○池，依汲古，宋元本皆作食。</p><h3 id="屯之巽" tabindex="-1">屯之巽 <a class="header-anchor" href="#屯之巽" aria-label="Permalink to “屯之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>久客無依，思歸故鄉。霖雨盛溢，道未得通。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽為商旅、為客，重巽故曰久客。伏坎為思，震為歸，艮為鄉，坎為雨，互大坎，故曰霖雨，曰盛溢。伏艮為道，坎陷故不通。○依，從宋元本，他本多作休。霖，宋元本作雷，從汲古本。</p><h3 id="屯之兌" tabindex="-1">屯之兌 <a class="header-anchor" href="#屯之兌" aria-label="Permalink to “屯之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>道路闢除，南至東遼。衛子善辭，使國無憂。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。為道路，震為闢除，為南，先天震東北，故曰東遼。震為衛、為子、為辭，艮初至五正反震，故曰善辭。艮為國，互坎為憂，震樂故無憂。○闢，各本多誤僻，闢除者，清治也，惟元本不訛。○此有故實，各家皆不能詳。案：《史記》：「朝鮮王衛滿，本燕人，自全燕時，常略屬遼東真番，後燕王盧綰反，滿率部東渡浿水，都王險，高後時，與遼東太守約為外臣，保塞外，滿遂王三世。林似指此事。</p><h3 id="屯之渙" tabindex="-1">屯之渙 <a class="header-anchor" href="#屯之渙" aria-label="Permalink to “屯之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>同枕共袍，中年相知。少賈無利，獨居愁思。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為枕，震為袍，中爻正反艮震，故曰同枕共袍。震為年，坎為中，故曰中年。伏兌為少，巽為賈、為利，風散，故無利。巽為寡，艮為居，故曰獨居。坎為憂思。○相知，汲古作分去，少賈作價少，均依宋元本。無利，宋本作無失，於下句文義不協，故從汲古。</p><h3 id="屯之節" tabindex="-1">屯之節 <a class="header-anchor" href="#屯之節" aria-label="Permalink to “屯之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>眾神集聚，相與議語。南國虐亂，百姓愁苦。興師徵討，更立賢主。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為神，坎為眾，故曰眾神。坎為集聚。二至五正反震，故曰相與議語。艮為國，震南，故曰南國，伏離為虐亂，震為百、為人，故曰百姓。上坎為愁苦，震為徵討，坎眾，故曰興師徵討。互震為主、為立，故曰更立賢主。○主，汲古本訛王，依宋元本。</p><h3 id="屯之中孚" tabindex="-1">屯之中孚 <a class="header-anchor" href="#屯之中孚" aria-label="Permalink to “屯之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>北陸閉蟄，隱伏不出。目盲耳聾，道路不通。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>通《小過》。中互大坎，坎為北陸，陸者，道也。《左傳》「日在北陸而藏冰」是也。坎為冬、為隱伏，故曰閉。巽為蟲，亦為伏，故曰閉蟄，曰不出。本卦互大離。目睛漲大故盲。《小過》互大坎耳空塞實，故聾。艮震為道路，坎塞，故不通。</p><h3 id="屯之小過" tabindex="-1">屯之小過 <a class="header-anchor" href="#屯之小過" aria-label="Permalink to “屯之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>痴狂妄作，心誑善惑。迷行失路，不知南北。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>此用屯象。震為狂，坤迷，故曰痴狂。坎為心、為惑，正覆震相背故曰誑。誑，妄語也。艮震為道路，震為南，坎為北，坎失，故不知。○誑，依宋本，元本作狂，非。迷行，依元本，汲古作迷惑。</p><h3 id="屯之既濟" tabindex="-1">屯之既濟 <a class="header-anchor" href="#屯之既濟" aria-label="Permalink to “屯之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>棟隆輔強，寵貴日光。福善並作，樂以高明。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用屯象。坎為極、為棟、為車、為輔，《大過》「棟橈之兇，不可以有輔也」，《詩》「勿棄爾輔」，《毛傳》「輔以佐車」。輔，夾車木也。坎在上，故曰棟隆，艮堅，故曰輔強。艮為日、為光、為寵貴，震為福善、為樂，艮為高明。</p><h3 id="屯之未濟" tabindex="-1">屯之未濟 <a class="header-anchor" href="#屯之未濟" aria-label="Permalink to “屯之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>愛我嬰女，牽衣不與。冀幸高貴，反日賤下。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此仍用屯象。震為嬰孩，坤為女，坎為愛，故曰愛我嬰女。震為衣，艮為手、為牽，艮止，故不與。艮為高貴、為求，故曰冀幸高貴。坤為賤下。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
